#!/usr/bin/env python3
"""bird_minidev: the oracle and do-nothing controls. Generated by `--kind files`.

    python3 data/datasets/bird_minidev/control.py --oracle
    python3 data/datasets/bird_minidev/control.py --noop
    python3 data/datasets/bird_minidev/control.py --oracle --platform
    python3 data/datasets/bird_minidev/control.py --noop   --platform

`data/scaffolds/command_control.py` carries the algorithm, and it is kind-agnostic: what is
dataset-specific is `oracle_files(task)` in `data/datasets/bird_minidev.py` -- the reference solution as
data. Gate 1 (oracle -> 1) and gate 2 (do nothing -> 0) are the same two commands for every
`command`/`files` dataset, which is the point of generating this file rather than writing it.
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))

from data.scaffolds import command_control  # noqa: E402


if __name__ == "__main__":
    raise SystemExit(command_control.control_main("bird_minidev", sys.argv[1:]))
